    how_cta_prompt: "If you want to learn more details about how XowApp works:",
    how_cta_deepdive: "How it works",
    deepdive_kicker: "How XowApp works",
    deepdive_title: "Showing photos without giving away copies or losing control",
    deepdive_intro: "XowApp lets you show your photos and videos to anyone you choose with total peace of mind, without anyone being able to save them to their phone or post them online.",
    deepdive_concept_showing_title: "Showing vs. Sharing",
    deepdive_concept_showing_body: "In normal apps, when you send a photo you give away a copy that anyone can save or forward. In XowApp, you only 'show': photos can only be viewed inside the app and cannot be downloaded. It's just like showing your photo album in person: your friends look at it, but the album stays with you.",
    deepdive_concept_albums_title: "Private and group albums",
