    whatis_kicker: "Què és",
    whatis_title: "Ensenyar les teves fotos i vídeos, no repartir-los",
    whatis_body: "XowApp és una app que et deixa ensenyar les teves fotos i vídeos a qui tu decideixis, directament al seu dispositiu — sense pujar-los a cap xarxa social ni a cap núvol que no controlis, i sense que es converteixin en una còpia que deixa de ser teva. Ensenyar no és el mateix que compartir: continues sent tu qui decideix què es veu, qui ho veu i durant quant de temps.",
    how_kicker: "Com funciona",
    how_title: "Tres passos, zero complicacions",
    how_step1_title: "1. Crea un àlbum",
    how_step1_body: "Tria qui pot veure'l. Ningú més hi entra si tu no l'hi convides.",
    how_step2_title: "2. Comparteix directament",
    how_step2_body: "Les fotos i vídeos viatgen xifrats del teu dispositiu al de l'altra persona. Ni tan sols nosaltres els podem veure.",
    how_step3_title: "3. Mantén el control",
    how_step3_body: "Decideix què es guarda, què caduca i què s'esborra. Esborrar vol dir esborrar, de debò.",
    how_cta_prompt: "Si vols conèixer més detalls sobre el funcionament de XowApp:",
    how_cta_deepdive: "Com funciona",
