    deepdive_title: "Ensenyar fotos sense regalar còpies ni perdre el control",
    deepdive_intro: "XowApp et permet ensenyar les teves fotos i vídeos a les persones que tu triïs amb total tranquil·litat, sense que ningú pugui desar-les a la galeria ni compartir-les a Internet.",
    deepdive_concept_showing_title: "Ensenyar vs. Compartir",
    deepdive_concept_showing_body: "En les aplicacions normals, en enviar una foto lliures una còpia que qualsevol pot desar o reenviar. A XowApp només «ensenyes»: les fotos només es poden veure dins de l'app i ningú les pot descarregar. És com ensenyar el teu àlbum de fotos en persona: els teus amics el miren, però l'àlbum es queda amb tu.",
    deepdive_concept_albums_title: "Àlbums privats i de grup",
    deepdive_concept_albums_body: "Crea àlbums privats amb una sola persona o àlbums compartits amb la teva família i amics. En tots ells tens el control total.",
    deepdive_concept_social_title: "Interaccions socials 100% privades",
    deepdive_concept_social_body: "Fes «M'agrada», comenta fotos i vídeos o xateja dins de cada àlbum amb els membres. Tots els comentaris, reaccions i missatges són completament privats i viatgen protegits.",
    deepdive_concept_security_title: "Accés biomètric i seguretat al teu mòbil",
    deepdive_concept_security_body: "Protegeix l'accés a l'app amb la teva empremta o el desbloqueig facial del teu telèfon. Tot es gestiona 100% en local al teu propi dispositiu. Les teves fotos i dades mai surten del teu mòbil sota cap concepte.",
