    usecase2_title: "2. Connectar amb un amic o familiar",
    usecase2_badge: "Connexió directa",
    usecase2_body: "Per enviar-se fotos, l'Anna i en Bernat es connecten entre si. Poden fer-ho buscant el nom d'usuari (@bernat), enviant un enllaç d'invitació per xat o escanejant un codi QR si estan junts. Els seus mòbils queden vinculats de forma privada i directa.",
