    profile_delete_modal_body: "Això esborrarà permanentment el teu compte, els teus àlbums, els enviaments enviats i rebuts, els teus contactes, comentaris, m'agrada i missatges dels nostres servidors. Aquesta acció no es pot desfer. Els informes de moderació associats al teu compte no s'eliminen.",
