    heroHeadline: "Le tue foto, solo per chi decidi tu.",
    heroSubtitle: "XowApp è l'album privato che invii direttamente, dal tuo cellulare a quello di chi scegli tu — senza caricarlo in nessun posto che non controlli tu.",
    hero_manifesto: "È \"MOSTRARE\", non condividere.",
    whatis_kicker: "Cos'è",
    whatis_title: "Mostrare le tue foto e i tuoi video, non distribuirli",
    whatis_body: "XowApp è un'app che ti permette di mostrare le tue foto e i tuoi video a chi decidi tu, direttamente sul suo dispositivo — senza caricarli su un social network né su un cloud che non controlli, e senza che diventino una copia che smette di essere tua. Mostrare non è lo stesso che condividere: sei sempre tu a decidere cosa si vede, chi lo vede e per quanto tempo.",
