    deepdive_intro: "XowApp ti permette di mostrare foto e video a chi vuoi in totale tranquillità, senza che nessuno possa salvarle nella propria galleria o pubblicarle su Internet.",
    deepdive_concept_showing_title: "Mostrare vs. Condividere",
    deepdive_concept_showing_body: "Nelle normali applicazioni, quando invii una foto consegni una copia che chiunque può salvare o inoltrare. Su XowApp ti limiti a «mostrare»: le foto possono essere viste solo all'interno dell'app e nessuno può scaricarle. È esattamente come mostrare il tuo album fotografico di persona: i tuoi amici lo guardano, ma l'album rimane con te.",
    deepdive_concept_albums_title: "Album privati e di gruppo",
    deepdive_concept_albums_body: "Crea album privati con una sola persona o album condivisi con la tua famiglia e i tuoi amici. In tutti hai il controllo totale.",
    deepdive_concept_social_title: "Interazioni sociali al 100% private",
    deepdive_concept_social_body: "Metti «Mi piace», commenta foto e video o chatta all'interno di ciascun album con i membri. Tutti i commenti, le reazioni e i messaggi sono totalmente privati e viaggiano protetti.",
