    heroHeadline: "Fotografiile tale, doar pentru cine decizi tu.",
    heroSubtitle: "XowApp este albumul privat pe care îl trimiți direct, de pe telefonul tău către cel al persoanei alese de tine — fără să îl încarci pe niciun site pe care nu îl controlezi.",
    hero_manifesto: "Este vorba despre „A ARĂTA”, nu a distribui.",
