    whatis_body: "XowApp este o aplicație care te lasă să arăți fotografiile și videoclipurile tale cui decizi tu, direct pe dispozitivul acelei persoane — fără să le încarci pe o rețea socială sau pe un cloud pe care nu îl controlezi, și fără să devină o copie care încetează să mai fie a ta. A arăta nu este același lucru cu a distribui: tot tu ești cel care decide ce se vede, cine vede și pentru cât timp.",
