    profile_delete_modal_title: "Eliminar a tua conta permanentemente?",
    profile_delete_modal_body: "Isto irá eliminar permanentemente a tua conta, os teus álbuns, os envios enviados e recebidos, os teus contactos, comentários, gostos e mensagens dos nossos servidores. Esta ação não pode ser anulada. As denúncias de moderação associadas à tua conta não são eliminadas.",
