    heroHeadline: "Dine billeder, kun til dem du vælger.",
    heroSubtitle: "XowApp er det private album, du sender direkte fra din telefon til den, du vælger — uden at uploade det til noget, du ikke selv har kontrol over.",
    hero_manifesto: "Det handler om at \"VISE\", ikke at dele.",
    whatis_kicker: "Hvad det er",
    whatis_title: "At vise dine billeder og videoer, ikke give dem fra dig",
    whatis_body: "XowApp er en app, der lader dig vise dine billeder og videoer til den, du vælger, direkte på deres enhed — uden at uploade dem til et socialt netværk eller en sky, du ikke har kontrol over, og uden at de bliver til en kopi, der holder op med at være din. At vise er ikke det samme som at dele: det er stadig dig, der bestemmer, hvad der bliver set, hvem der ser det, og hvor længe.",
