    transparencia_phase_pro_name: "المرحلة ٣ · الرسمنة",
    transparencia_phase_pro_desc: "تحويل المشروع إلى كيان رسمي: تأسيس شركة، محاسبة، استشارات قانونية وحماية بيانات، تأمين، وتسجيل العلامة التجارية. هذه هي المرحلة الأخيرة عن قصد — لا معنى لإضفاء الطابع الرسمي على الهيكل قبل تأمين الخدمة نفسها.",
